public static String reverse(final String str) {
    if (str == null) {
        return null;
    }
    int length = str.length();
    if (length <= 1) {
        return str;
    }
    int mid = length / 2;
    char[] chars = str.toCharArray();
    char temp;
    for (int i = 0; i < mid; i++) {
        temp = chars[i];
        chars[i] = chars[length - 1 - i];
        chars[length - 1 - i] = temp;
    }
    return new String(chars);
}

