// Check if a number is prime
private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    } else if (n == 2 || n == 3) {
        return true;
    } else if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }

    // Perform the Miller-Rabin primality test with a certain number of iterations
    int iterations = 10;
    for (int i = 0; i < iterations; i++) {
        if (!passesMillerRabinTest(n)) {
            return false;
        }
    }

    return true;
}

// Passes the Miller-Rabin primality test
private static boolean passesMillerRabinTest(int n) {
    if (n == 2 || n == 3) {
        return true;
    }

    BigInteger d = n - 1;
    int s = 0;
    while (d % 2 == 0) {
        d /= 2;
        s++;
    }

    BigInteger r = new BigInteger(Integer.toString(2));
    while (s > 0) {
        r = r.modPow(d, n);
        if (r.equals(BigInteger.ONE) || r.equals(n - 1)) {
            return true;
        }
        s--;
    }

    return false;
}
