        for (Map.Entry<String,JsonElement> entry : jsonObject.entrySet()) { // Iterate over the entries in the JSON object
            String key = entry.getKey();
            JsonElement value = entry.getValue();

            if (value.isJsonObject()) { // Check if the value is a JSON object
                content.put(key, buildContent(value.getAsJsonObject())); // Build the child content recursively
            }
            else if (value.isJsonArray()) {
                content.put(key, buildArrayContent(value.getAsJsonArray())); // Build the array content
            }
            else {
                content.put(key, value.getAsJsonPrimitive().getValue()); // Get the primitive value
            }
        }
    }

    return content;
}
