private static char decodeHexNibble(final char c) {
    // check if c is a valid hexadecimal character
    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
        return Character.MAX_VALUE;
    }

    // convert c to lowercase
    final char lowercaseC = Character.toLowerCase(c);

    // subtract 1 if c is in the range 'a' - 'f'
    int nibble = lowercaseC - 'a' + 1;
    if (nibble > 0) {
        nibble -= 'a' - '0';
    }

    // convert the nibble to a char
    return (char)nibble;
}

